create table midad_private.bridge_config(id text primary key,secret_hash text not null unique,site_url text not null);
create table midad_private.bridge_pending(nonce text primary key,bridge_id text not null references midad_private.bridge_config(id) on delete cascade,subject text not null,requester_email text not null default '',expires_at timestamptz not null default now()+interval '10 minutes',used boolean not null default false);
create table midad_private.bridge_links(bridge_id text not null references midad_private.bridge_config(id) on delete cascade,subject text not null,user_id uuid not null references auth.users(id) on delete cascade,project_id uuid references public.midad_projects(id) on delete cascade,allow_write boolean not null default false,created_at timestamptz not null default now(),primary key(bridge_id,subject));
create table midad_private.ai_writes(user_id uuid not null references auth.users(id) on delete cascade,request_id uuid not null,args_hash text not null,response jsonb not null,primary key(user_id,request_id));
do $$declare t text;begin foreach t in array array['bridge_config','bridge_pending','bridge_links','ai_writes'] loop execute format('alter table midad_private.%I enable row level security',t);execute format('create policy deny_clients on midad_private.%I for all to anon,authenticated using(false) with check(false)',t);end loop;end$$;
create function public.midad_bridge_request(secret_hash text,subject_id text,email text,nonce text) returns boolean language plpgsql security definer set search_path='' as $$declare bid text;begin select id into bid from midad_private.bridge_config c where c.secret_hash=midad_bridge_request.secret_hash;if bid is null or length(subject_id)>300 or length(nonce)<40 then raise exception 'invalid_bridge';end if;delete from midad_private.bridge_pending where expires_at<now();insert into midad_private.bridge_pending(nonce,bridge_id,subject,requester_email) values(nonce,bid,subject_id,left(email,254));return true;end$$;
create function public.midad_bridge_identity(secret_hash text,subject_id text) returns table(user_id uuid,project_id uuid,allow_write boolean) language sql stable security definer set search_path='' as $$select l.user_id,l.project_id,l.allow_write from midad_private.bridge_links l join midad_private.bridge_config c on c.id=l.bridge_id where c.secret_hash=midad_bridge_identity.secret_hash and l.subject=subject_id$$;
create function public.midad_bridge_link_details(request_nonce text) returns table(requester_email text,site_url text) language sql stable security definer set search_path='' as $$select p.requester_email,c.site_url from midad_private.bridge_pending p join midad_private.bridge_config c on c.id=p.bridge_id where p.nonce=request_nonce and p.expires_at>now() and not p.used and auth.uid() is not null$$;
create function public.midad_bridge_authorize(request_nonce text,novel_id uuid,write_access boolean) returns boolean language plpgsql security definer set search_path='' as $$declare p midad_private.bridge_pending;begin if auth.uid() is null then raise exception 'login_required';end if;select * into p from midad_private.bridge_pending where nonce=request_nonce and not used and expires_at>now() for update;if p.nonce is null then raise exception 'link_expired';end if;if novel_id is not null and not exists(select 1 from public.midad_projects where id=novel_id and user_id=auth.uid()) then raise exception 'not_owner';end if;if exists(select 1 from midad_private.bridge_links where bridge_id=p.bridge_id and subject=p.subject and user_id<>auth.uid()) then raise exception 'already_linked_to_another_account';end if;insert into midad_private.bridge_links(bridge_id,subject,user_id,project_id,allow_write) values(p.bridge_id,p.subject,auth.uid(),novel_id,write_access) on conflict(bridge_id,subject) do update set project_id=excluded.project_id,allow_write=excluded.allow_write;update midad_private.bridge_pending set used=true where nonce=request_nonce;return true;end$$;
create function public.midad_connected_apps() returns table(id text,site_url text,project_id uuid,allow_write boolean) language sql stable security definer set search_path='' as $$select c.id,c.site_url,l.project_id,l.allow_write from midad_private.bridge_links l join midad_private.bridge_config c on c.id=l.bridge_id where l.user_id=auth.uid()$$;
create function public.midad_disconnect_app(bridge text) returns void language sql security definer set search_path='' as $$delete from midad_private.bridge_links where bridge_id=bridge and user_id=auth.uid()$$;
revoke all on function public.midad_bridge_request(text,text,text,text),public.midad_bridge_identity(text,text) from public,anon,authenticated;
grant execute on function public.midad_bridge_request(text,text,text,text),public.midad_bridge_identity(text,text) to service_role;
revoke all on function public.midad_bridge_link_details(text),public.midad_bridge_authorize(text,uuid,boolean),public.midad_connected_apps(),public.midad_disconnect_app(text) from public,anon;
grant execute on function public.midad_bridge_link_details(text),public.midad_bridge_authorize(text,uuid,boolean),public.midad_connected_apps(),public.midad_disconnect_app(text) to authenticated;
create function public.midad_ai_create(operation text,owner_id uuid,novel_id uuid,title text,description text,story text,document jsonb,prose text,request_key uuid) returns jsonb language plpgsql security definer set search_path='' as $$declare response jsonb;h text;b uuid;c uuid;p uuid;old midad_private.ai_writes;begin
 if length(title) not between 1 and 200 or length(prose)>1000000 then raise exception 'invalid_input';end if;
 h:=encode(extensions.digest(concat_ws('|',operation,novel_id,title,description,story,document::text,prose),'sha256'),'hex');perform pg_advisory_xact_lock(hashtextextended(owner_id::text||request_key::text,0));select * into old from midad_private.ai_writes where user_id=owner_id and request_id=request_key;if old.request_id is not null then if old.args_hash<>h then raise exception 'request_key_reused';end if;return old.response;end if;
 if operation='create_novel' then insert into public.midad_projects(user_id,title,description,story) values(owner_id,title,description,story) returning id into p;insert into public.midad_books(user_id,project_id,title) values(owner_id,p,title) returning id into b;response:=jsonb_build_object('novel_id',p,'title',title);
 elsif operation='create_chapter' then if not exists(select 1 from public.midad_projects where id=novel_id and user_id=owner_id) then raise exception 'not_owner';end if;select id into b from public.midad_books where project_id=novel_id and user_id=owner_id order by position,id limit 1;if b is null then insert into public.midad_books(user_id,project_id,title) select owner_id,novel_id,p.title from public.midad_projects p where id=novel_id returning id into b;end if;insert into public.midad_chapters(user_id,book_id,title,position) values(owner_id,b,title,(select coalesce(max(position),-1)+1 from public.midad_chapters where book_id=b and draft_id is null)) returning id into c;insert into public.midad_scenes(user_id,chapter_id,title,content,plain_text) values(owner_id,c,title,document,prose);response:=jsonb_build_object('chapter_id',c,'novel_id',novel_id,'title',title,'version',0);
 else raise exception 'unknown_operation';end if;insert into midad_private.ai_writes(user_id,request_id,args_hash,response) values(owner_id,request_key,h,response);return response;end$$;
create function public.midad_ai_save_chapter(owner_id uuid,cid uuid,expected integer,document jsonb,prose text) returns jsonb language plpgsql security definer set search_path='' as $$declare s public.midad_scenes;begin if not exists(select 1 from public.midad_chapters where id=cid and user_id=owner_id) then raise exception 'not_owner';end if;if (select count(*) from public.midad_scenes where chapter_id=cid)<>1 then raise exception 'chapter_has_multiple_scenes';end if;select * into s from public.midad_scenes where chapter_id=cid and user_id=owner_id for update;if s.version<>expected then raise exception 'version_conflict';end if;insert into public.midad_revisions(user_id,scene_id,content,plain_text,version) values(owner_id,s.id,s.content,s.plain_text,s.version);update public.midad_scenes set content=document,plain_text=prose,version=version+1,updated_at=now() where id=s.id;return jsonb_build_object('chapter_id',cid,'version',expected+1,'saved',true);end$$;
revoke all on function public.midad_ai_create(text,uuid,uuid,text,text,text,jsonb,text,uuid),public.midad_ai_save_chapter(uuid,uuid,integer,jsonb,text) from public,anon,authenticated;
grant execute on function public.midad_ai_create(text,uuid,uuid,text,text,text,jsonb,text,uuid),public.midad_ai_save_chapter(uuid,uuid,integer,jsonb,text) to service_role;
